import openpyxl

path='/root/additional_shift_blocks_needed_august_2025.xlsx'
wb=openpyxl.load_workbook(path, data_only=False)
ws=wb['Unit_Results']

# Check that date columns are strings, not datetime
# Columns: Projected_Understaff_Date (5), Required_Shift_Start_Date (11), Earliest_Scheduled_Shift_Date (14)
for r in range(7, ws.max_row+1):
    cu=ws.cell(r,1).value
    if cu is None:
        continue
    for c, name in [(5,'Projected_Understaff_Date'),(11,'Required_Shift_Start_Date'),(14,'Earliest_Scheduled_Shift_Date')]:
        v=ws.cell(r,c).value
        if v is None:
            continue
        if not isinstance(v, str):
            raise SystemExit(f"{cu} {name} expected str, got {type(v).__name__}: {v!r}")

# Check booleans are real bool
for r in range(7, ws.max_row+1):
    cu=ws.cell(r,1).value
    if cu is None:
        continue
    for c, name in [(12,'Rounding_Applied'),(13,'Earlier_Shift_Required')]:
        v=ws.cell(r,c).value
        if not isinstance(v, bool):
            raise SystemExit(f"{cu} {name} expected bool, got {type(v).__name__}: {v!r}")

print('Type checks passed for date strings and booleans.')
